1	import AVFoundation
2	import AppKit
3	import ScreenCaptureKit
4	
5	/// `record_screen`'s ARGUMENT vocabulary and the lookup the arguments meet —
6	/// the second cut off `AgentServer+Recording.swift` (R1 review; the first is
7	/// `+RecordingResult.swift`), taken when the fixes put that file at 481
8	/// lines against the 400-line cap for a new file. The seam is the sentence
9	/// its header had used to describe itself: "the wait around the recorder
10	/// and the argument vocabulary in front of it" — the wait stayed, the
11	/// vocabulary came here, and with it the shareable-content call and the
12	/// display ordering, because they are what the `display` and `window`
13	/// arguments RESOLVE against and nothing else reads them. Every function is
14	/// pure in the arguments, or a wait on one framework answer; none touches
15	/// the recorder. `private` → internal is the whole cost.
16	///
17	/// **The refusal ORDER is decided in the caller**, `recordScreen`, which
18	/// calls these in the order the header there fixes: the caller's own
19	/// mistakes, the grant, the lookup. Nothing here reads a grant.
20	extension AgentServer {
21	
22	    // MARK: - The arguments
23	
24	    /// `source`: what is recorded — the screen (the default), the
25	    /// microphone alone (the panel's Microphone Only, spec §11 recording) or
26	    /// a camera alone (spec §11 CAM-4, `+RecordingCamera.swift`).
27	    enum RecordingSourceKind: String, CaseIterable {
28	        case screen
29	        case voiceOver = "voice_over"
30	        case camera
31	    }
32	
33	    /// The arguments a voice-over refuses by name: everything that only a
34	    /// picture or the stream reads.
35	    static let voiceOverScreenOnlyArguments = [
36	        "display", "window", "system_audio", "show_clicks", "size", "include_framejob_windows",
37	        "auto_zoom", "shortcut_overlays", "speed_up_typing",
38	        "keys", "cursor",
39	    ]
40	
41	    /// `source`, default `screen`; an unknown value refused with the
42	    /// vocabulary; then the camera's argument checks (CAM-4: `camera` with
43	    /// another source, a camera's own strangers). For `voice_over`, the
44	    /// screen-only arguments the caller
45	    /// GAVE (a JSON null is not given, `scalarArg`'s rule) are refused
46	    /// together, in `voiceOverScreenOnlyArguments` order, then
47	    /// `microphone: false`.
48	    func recordingSourceKind(_ a: [String: Any]) throws -> RecordingSourceKind {
49	        let kind = try enumArg(a, "source", RecordingSourceKind.self) ?? .screen
50	        try recordingCameraStrangers(a, kind: kind)
51	        guard kind == .voiceOver else { return kind }
52	        let strangers = Self.voiceOverScreenOnlyArguments.filter { a[$0] != nil && !(a[$0] is NSNull) }
53	        guard strangers.isEmpty else {
54	            throw ToolError(
55	                message: "With source voice_over, " + strangers.joined(separator: ", ")
56	                    + " cannot be given — a voice-over records the microphone alone.")
57	        }
58	        if try boolArg(a, "microphone") == false {
59	            throw ToolError(
60	                message: "With source voice_over, microphone cannot be false — a voice-over "
61	                    + "records the microphone alone.")
62	        }
63	        return kind
64	    }
65	
66	    /// `seconds`: required, 1…600. Spelled back as the caller sent it (`0`,
67	    /// not `0.0`) when it is whole.
68	    func recordingSeconds(_ a: [String: Any]) throws -> Double {
69	        guard let seconds = try doubleArg(a, "seconds") else {
70	            throw ToolError(message: "Missing required argument: seconds")
71	        }
72	        guard seconds >= 1, seconds <= 600 else {
73	            let whole = seconds == seconds.rounded() && abs(seconds) < 1e15
74	            let spelled = whole ? String(Int(seconds)) : String(seconds)
75	            throw ToolError(message: "seconds must be 1…600 (got \(spelled)).")
76	        }
77	        return seconds
78	    }
79	
80	    /// `display` (an index, default 0) and `window` (a CGWindowID), at most
81	    /// one; the index meets the LIST later, once it can be asked for.
82	    func recordingSourceArguments(_ a: [String: Any]) throws -> (Int, CGWindowID?) {
83	        let display = try intArg(a, "display")
84	        let window = try intArg(a, "window")
85	        guard display == nil || window == nil else {
86	            throw ToolError(
87	                message: "Pass display or window, not both — a recording is of one or the other.")
88	        }
89	        if let display, display < 0 {
90	            throw ToolError(message: "display must be 0 or more (got \(display)).")
91	        }
92	        var windowID: CGWindowID?
93	        if let window {
94	            guard window >= 0, window <= Int(CGWindowID.max) else {
95	                throw ToolError(message: "window must be a CGWindowID (got \(window)).")
96	            }
97	            windowID = CGWindowID(window)
98	        }
99	        return (display ?? 0, windowID)
100	    }
101	
102	    /// `enhance` (spec §11 AU-69 (d)), default false: true needs a microphone,
103	    /// then a clip to enhance — `place` — refused in that order.
104	    func recordingEnhance(_ a: [String: Any], microphone: Bool, place: Bool) throws -> Bool {
105	        guard try boolArg(a, "enhance") ?? false else { return false }
106	        guard microphone else {
107	            throw ToolError(
108	                message: "enhance: true enhances the microphone's clip, so it needs "
109	                    + "microphone: true (or source voice_over).")
110	        }
111	        guard place else {
112	            throw ToolError(
113	                message: "enhance: true needs place: true — with place: false the microphone "
114	                    + "lands as media with no clip to enhance.")
115	        }
116	        return true
117	    }
118	
119	    /// `size`: `nominal` (default) or `best`, `requestedFrameFormat`'s form.
120	    func recordingResolution(_ a: [String: Any]) throws -> RecordingResolution {
121	        try enumArg(a, "size", RecordingResolution.self, folding: true) ?? .nominal
122	    }
123	
124	    /// `path`, the FOLDER: trimmed, tilde-expanded, and an empty or blank
125	    /// string counting as absent — `RecordingFiles.folder()` then applies —
126	    /// because `URL(fileURLWithPath: "")` is the process's working directory,
127	    /// and a recording written into whatever `cwd` the app was launched
128	    /// from is a file nobody can find.
129	    func recordingFolder(_ a: [String: Any]) throws -> URL? {
130	        guard let raw = try stringArg(a, "path") else { return nil }
131	        let trimmed = raw.trimmingCharacters(in: .whitespacesAndNewlines)
132	        guard !trimmed.isEmpty else { return nil }
133	        return URL(
134	            fileURLWithPath: (trimmed as NSString).expandingTildeInPath, isDirectory: true)
135	    }
136	
137	    /// Where the recording will land, decided BEFORE it starts. A named
138	    /// `project` goes through `target(_:)` and its refusal stands; no name
139	    /// and no document is `.newProject`; otherwise the frontmost. Main.
140	    func recordingDestination(_ a: [String: Any]) throws -> RecordingDestination {
141	        if try stringArg(a, "project") != nil {
142	            return .document(recipeKey: try target(a).recipeKey)
143	        }
144	        if openProjects().isEmpty { return .newProject }
145	        return .document(recipeKey: try target(a).recipeKey)
146	    }
147	
148	    // MARK: - The content
149	
150	    /// `ScreenRecorder.shareableContent`, CALLED from this thread (the helper
151	    /// issues the framework call from a global queue and hops the completion
152	    /// to main whatever thread asks) and waited for here. Not through
153	    /// `onMain`: on a locked console the framework held the calling thread
154	    /// ~37 s before answering nothing — main's, through a hop.
155	    func shareableContent() throws -> SCShareableContent {
156	        let semaphore = DispatchSemaphore(value: 0)
157	        let box = AgentBox<Result<SCShareableContent, Error>>()
158	        ScreenRecorder.shareableContent { outcome in
159	            box.value = outcome
160	            semaphore.signal()
161	        }
162	        guard semaphore.wait(timeout: .now() + 20) == .success else {
163	            throw ToolError(message: "Timed out listing the shareable displays and windows.")
164	        }
165	        switch box.value {
166	        case .success(let content): return content
167	        case .failure(let error): throw ToolError(message: error.localizedDescription)
168	        case nil:
169	            throw ToolError(message: "The shareable displays and windows could not be listed.")
170	        }
171	    }
172	
173	    /// The shareable displays, MAIN first — so `display` 0 means what the
174	    /// catalog says whatever order the framework lists them in.
175	    static func orderedDisplays(_ content: SCShareableContent) -> [SCDisplay] {
176	        let main = CGMainDisplayID()
177	        return content.displays.filter { $0.displayID == main }
178	            + content.displays.filter { $0.displayID != main }
179	    }
180	
181	    /// The source the two arguments name. A window id naming nothing
182	    /// shareable is refused by `ScreenRecorder.filter(for:in:excluding:)`'s sentence.
183	    /// An EMPTY display list is a fact about the host — the console is
184	    /// locked or every display is asleep (measured: a true preflight and
185	    /// zero displays, the night the proof was written) — and is named as
186	    /// that, BEFORE the range sentence, which would otherwise read
187	    /// "display must be 0…0 (got 0)" for a caller who asked for nothing odd.
188	    func recordingSource(
189	        _ displayIndex: Int, _ windowID: CGWindowID?, in content: SCShareableContent
190	    ) throws -> RecordingSource {
191	        if let windowID { return .window(windowID) }
192	        let displays = Self.orderedDisplays(content)
193	        guard !displays.isEmpty else {
194	            throw ToolError(
195	                message: "No display is shareable right now — the console is locked or every "
196	                    + "display is asleep; nothing can be recorded until one is.")
197	        }
198	        guard displayIndex < displays.count else {
199	            throw ToolError(
200	                message: "display must be 0…\(displays.count - 1) (got \(displayIndex)); "
201	                    + "\(displays.count) display\(displays.count == 1 ? " is" : "s are") "
202	                    + "shareable.")
203	        }
204	        return .display(displays[displayIndex].displayID)
205	    }
206	}
