3	/// `record_screen`'s polish on landing (road map "creator-jobs" CU10, spec §11 CU-100…CU-102):
4	/// the three arguments `auto_zoom`, `shortcut_overlays` and `speed_up_typing` and their
5	/// refusals, and the tool door's follow-up after `land` and any Enhance Voice — the panel's
6	/// "When it lands:" boxes without the panel. Every command is its tool's own body
7	/// (`autoZoom(document:clips:settings:)` and the two beside it) at the tools' defaults, since a
8	/// tool reads no `UserDefaults`, each its own undo step.
9	extension AgentServer {
10	
11	    /// The three booleans (default false), in the order auto_zoom, shortcut_overlays,
12	    /// speed_up_typing, each refused without `place` and the last two without `keys:
13	    /// "shortcuts"` (CU-102 (b)); read after `enhance`, before any grant. With voice_over or
14	    /// camera they never reach here: the source's stranger lists refuse them by name.
15	    func recordingPolish(_ a: [String: Any], place: Bool, keys: RecordingKeys) throws
16	        -> [RecordingPolish.Command]
17	    {
18	        var asked: [RecordingPolish.Command] = []
19	        for command in RecordingPolish.Command.allCases {
20	            guard try boolArg(a, command.rawValue) ?? false else { continue }
21	            if !place { throw ToolError(message: Self.polishNeedsPlace(command)) }
22	            if command != .autoZoom, keys != .shortcuts {
23	                throw ToolError(message: Self.polishNeedsKeys(command))
24	            }
25	            asked.append(command)
26	        }
27	        return asked
28	    }
29	
30	    /// CU-102 (b)'s `place` sentences.
31	    static func polishNeedsPlace(_ command: RecordingPolish.Command) -> String {
32	        switch command {
33	        case .autoZoom:
34	            return "auto_zoom: true plans on the landed screen clips, so it needs place: true."
35	        case .shortcutOverlays:
36	            return "shortcut_overlays: true places overlays over the landed screen clips, so it "
37	                + "needs place: true."
38	        case .speedUpTyping:
39	            return "speed_up_typing: true speeds up the landed screen clips' typing, so it needs "
40	                + "place: true."
41	        }
42	    }
43	
44	    /// CU-102 (b)'s `keys` sentences (none for auto_zoom, which zooms on clicks too).
45	    static func polishNeedsKeys(_ command: RecordingPolish.Command) -> String {
46	        let what = command == .speedUpTyping ? "typing to speed up" : "shortcut to show"
47	        return "\(command.rawValue): true needs keys: \"shortcuts\" — without it the cursor file "
48	            + "records no \(what)."
49	    }
50	
51	    /// SERVER THREAD. CU-101 (j): for each command the choice asks for, in order, `decide`
52	    /// polled through `onMain` every `RecordingPolish.checkInterval`, then the tool's body; its
53	    /// answer object under the command's name, or a sentence under `<name>_error`. On `.drop`,
54	    /// `.giveUp` or the call's cancel, every command not yet run gets its sentence. The cursor
55	    /// files are read here, once, for the speed-up's readiness; a read that fails counts as
56	    /// ready, so the body says why.
57	    func polishLanded(
58	        _ result: RecordingResult, in document: ProjectDocument, into fields: inout [String: Any]
59	    ) {
60	        var remaining = RecordingPolish.commands(of: result.choice)
61	        guard !remaining.isEmpty else { return }
62	        let stop = AgentLane.shared.callCancel
63	        let paths = RecordingPolish.screenPaths(of: result)
64	        let scope = onMain { document.scope }
65	        var tracks: [UInt32: ReelCursor]?
66	        var started = Date()
67	        func fail(_ sentence: (RecordingPolish.Command) -> String) {
68	            for command in remaining { fields[command.rawValue + "_error"] = sentence(command) }
69	            remaining = []
70	        }
71	        while let command = remaining.first {
72	            if stop?.isCancelled == true {
73	                fail(RecordingPolish.stoppedSentence)
74	                break
75	            }
76	            if command == .speedUpTyping, tracks == nil {
77	                let files = onMain { () -> [UInt32: URL] in
78	                    let snapshot = document.editedProject.snapshot
79	                    let clips = RecordingPolish.screenClips(paths, in: document)
80	                    return (try? AutoZoom.cursorFiles(
81	                        clips.compactMap { snapshot.clip($0) }, in: snapshot)) ?? [:]
82	                }
83	                tracks = (try? AutoZoom.readTracks(files)) ?? [:]
84	            }
85	            let held = tracks ?? [:]
86	            let step = onMain { () -> RecordingPolish.Step in
87	                let clips = RecordingPolish.screenClips(paths, in: document)
88	                let ready =
89	                    !clips.isEmpty
90	                    && RecordingPolish.isReady(
91	                        command, clips: clips, tracks: held, speedUp: SpeedUpTypingSettings(),
92	                        in: document)
93	                return RecordingPolish.decide(
94	                    command: command, clips: clips,
95	                    enhancing: RecordingEnhance.isPending(document), ready: ready,
96	                    busy: RecordingEnhance.isBusy(document, scope: scope),
97	                    elapsed: Date().timeIntervalSince(started))
98	            }
99	            switch step {
100	            case .wait:
101	                Thread.sleep(forTimeInterval: RecordingPolish.checkInterval)
102	            case .drop:
103	                fail(RecordingPolish.noScreenSentence)
104	            case .giveUp:
105	                fail { RecordingPolish.notReadySentence($0, tool: true) }
106	            case .run(let ran, let clips):
107	                do {
108	                    let answer = try polish(ran, document: document, clips: clips)
109	                    fields[ran.rawValue] = Self.resultObject(answer) ?? answer
110	                } catch let error as ToolError {
111	                    fields[ran.rawValue + "_error"] = error.message
112	                } catch {
113	                    fields[ran.rawValue + "_error"] = error.localizedDescription
114	                }
115	                remaining.removeFirst()
116	                started = Date()
117	            }
118	        }
119	        onMain { RecordingPolish.forgetWait(document) }
120	    }
121	
122	    /// One command through its tool's body at the tools' defaults. SERVER THREAD.
123	    private func polish(
124	        _ command: RecordingPolish.Command, document: ProjectDocument, clips: [UInt32]
125	    ) throws -> String {
126	        switch command {
127	        case .autoZoom:
128	            return try autoZoom(document: document, clips: clips, settings: AutoZoomSettings())
129	        case .shortcutOverlays:
130	            return try addShortcutOverlays(
131	                document: document, clips: clips, settings: ShortcutOverlaySettings())
132	        case .speedUpTyping:
133	            return try speedUpTyping(
134	                document: document, clips: clips, settings: SpeedUpTypingSettings())
135	        }
136	    }
137	}
