1	import AppKit
2	
3	/// `record_screen`'s LANDING (camera-recording CR3-0): `awaitGestureEnd`, the
4	/// wait for a target document's drag to end, and `land`, the two doors a
5	/// finished recording takes — a document through `editResult`, a new project
6	/// through `ProjectDocument.untitled(around:)`. A pure move out of
7	/// `AgentServer+Recording.swift` at the 400-line cap, landed alone before
8	/// camera + screen grows the tool; nothing in either body changed, and
9	/// `private` → internal is the whole cost, because a `private` extension
10	/// member reaches only its own file. What the answer and its refusals say is
11	/// `AgentServer+RecordingResult.swift` and `+RecordingSentences.swift`.
12	extension AgentServer {
13	    // MARK: - The landing
14	
15	    /// SERVER THREAD. A target document mid-drag is not committed over the
16	    /// gesture's base handle (`RecordingLanding.placement` refuses by name);
17	    /// the panel retries from a half-second timer bounded at forty tries,
18	    /// and this polls `isLiveEditing` through `onMain` at that interval and
19	    /// bound BY NAME, so the two doors cannot drift. A gesture outlasting
20	    /// the bound still reaches `placement`'s refusal, which names the file;
21	    /// a `.newProject` target or a closed document has nothing to wait for.
22	    func awaitGestureEnd(_ destination: RecordingDestination) {
23	        for _ in 0..<RecorderPanelController.landingRetryLimit {
24	            let dragging = onMain { () -> Bool in
25	                guard case .document(let document) = RecordingLanding.resolve(destination)
26	                else { return false }
27	                return document.isLiveEditing
28	            }
29	            guard dragging else { return }
30	            Thread.sleep(forTimeInterval: RecorderPanelController.landingRetryInterval)
31	        }
32	    }
33	
34	    /// MAIN. The two doors: a document through `editResult` (one undo step,
35	    /// the `created` ids, the scope landing); a new project through
36	    /// `ProjectDocument.untitled(around:)`, which does everything. Every
37	    /// throw past this point is `savedButNotAdded`'s: every segment's files
38	    /// exist. The result is `recordingFields` over the segments plus the ids
39	    /// each door knows them by (the placement's lists, predicted before the
40	    /// commit; the new project's snapshot, read by path), and `note` is the
41	    /// door's sentences in order: `place: false`, a closed target, what the
42	    /// landing could NOT place (each naming its file), then `resultNotes(result)`.
43	    /// Answers the document it landed in beside the answer, for
44	    /// `landAndEnhance`.
45	    func land(_ result: RecordingResult, place: Bool) throws
46	        -> (answer: String, document: ProjectDocument)
47	    {
48	        var fields: [String: Any]
49	        var notes: [String] = []
50	        switch RecordingLanding.resolve(result.choice.destination) {
51	        case .document(let document):
52	            let placement: RecordingLanding.Placement
53	            do {
54	                placement = try RecordingLanding.placement(result, in: document, place: place)
55	            } catch {
56	                throw Self.savedButNotAdded(result, error)
57	            }
58	            fields = Self.recordingFields(
59	                result, ids: Self.documentIds(result, placement: placement),
60	                leftOutIds: Self.documentLeftOutIds(result, placement: placement))
61	            fields["landed"] = "document"
62	            if !place {
63	                notes.append(
64	                    "The recording is in the project's media list but not on the timeline — "
65	                        + "place it with add_clip {track, media, at}.")
66	            }
67	            notes.append(contentsOf: placement.notes)
68	            notes.append(contentsOf: Self.resultNotes(result))
69	            if !notes.isEmpty { fields["note"] = notes.joined(separator: " ") }
70	            let answer: String
71	            do {
72	                answer = try editResult(document, RecordingLanding.actionName, placement.ops, fields)
73	            } catch {
74	                throw Self.savedButNotAdded(result, error)
75	            }
76	            // `editResult` commits and does not build caches; `importMedia`
77	            // calls this after its own commit for the same reason.
78	            document.generateCaches()
79	            return (answer, document)
80	        case .newProject:
81	            let document: ProjectDocument
82	            var landingNotes: [String] = []
83	            do {
84	                let landing = try ProjectDocument.untitled(around: result)
85	                document = landing.document
86	                landingNotes = landing.notes
87	            } catch {
88	                throw Self.savedButNotAdded(result, error)
89	            }
90	            fields = Self.recordingFields(
91	                result, ids: Self.newProjectIds(result, in: document),
92	                leftOutIds: Self.newProjectLeftOutIds(result, in: document))
93	            fields["landed"] = "new_project"
94	            if result.choice.destination != .newProject {
95	                notes.append(
96	                    "The target document closed while the recording ran, so it opened as a "
97	                        + "new project instead.")
98	            }
99	            if !place {
100	                notes.append(
101	                    "place: false has no meaning for a new project — the "
102	                        + (result.isVoiceOver ? "voice-over" : "picture") + " IS the "
103	                        + "document, so its clips are on the timeline, one per segment and "
104	                        + "the first at 0.")
105	            }
106	            notes.append(contentsOf: landingNotes)
107	            notes.append(contentsOf: Self.resultNotes(result))
108	            if !notes.isEmpty { fields["note"] = notes.joined(separator: " ") }
109	            fields["ok"] = true
110	            fields["project"] = summary(document)
111	            return (try jsonResult(fields), document)
112	        }
113	    }
114	
115	    /// SERVER THREAD. `land` on main, and in the same hop, when the choice
116	    /// asks for it, Remove Background over the camera clips as its own step
117	    /// (road map creator-jobs CO8, spec §11 CO-81, `camera_cutout` or
118	    /// `camera_cutout_error`); then, when the choice asks for it,
119	    /// Enhance Voice over the recording's voice clips as its own step (spec
120	    /// §11 AU-68 (f)): `decide` polled through `onMain` every
121	    /// `RecordingEnhance.checkInterval`, then `enhance_voice`'s own body at
122	    /// its default target (a tool reads no `UserDefaults`); then, when it asks
123	    /// for any, the polish on landing (road map creator-jobs CU10, spec §11
124	    /// CU-101 (j), `polishLanded`). The answer is `land`'s with `enhance`
125	    /// (that body's answer) or `enhance_error`, the polish's answers or
126	    /// `…_error` sentences, and `project` read again, last, when any ran.
127	    func landAndEnhance(_ result: RecordingResult, place: Bool) throws -> String {
128	        let stop = AgentLane.shared.callCancel
129	        let (answer, document, cutout) = try onMain {
130	            () throws -> (String, ProjectDocument, [UInt32]) in
131	            let (answer, document) = try self.land(result, place: place)
132	            // CO-81: Remove Background, its own step, before Enhance Voice and the polish.
133	            return (answer, document, RecordingCutout.apply(result, in: document))
134	        }
135	        let polish = !RecordingPolish.commands(of: result.choice).isEmpty
136	        let wantsCutout = result.choice.cameraCutout
137	        guard result.choice.enhanceMicrophone || polish || wantsCutout else { return answer }
138	        var fields = Self.resultObject(answer) ?? [:]
139	        if wantsCutout {
140	            if cutout.isEmpty {
141	                fields["camera_cutout_error"] = RecordingCutout.noCameraSentence
142	            } else {
143	                fields["camera_cutout"] = ["clips": cutout]
144	            }
145	        }
146	        if result.choice.enhanceMicrophone {
147	            try enhanceLanded(result, in: document, stop: stop, into: &fields)
148	        }
149	        if polish { polishLanded(result, in: document, into: &fields) }
150	        fields["project"] = onMain { self.summary(document) }
151	        return try jsonResult(fields)
152	    }
153	
154	    /// SERVER THREAD. AU-68 (f)'s wait and Enhance Voice, its answer or
155	    /// `enhance_error` written into `fields`.
156	    private func enhanceLanded(
157	        _ result: RecordingResult, in document: ProjectDocument, stop: AgentCallCancel?,
158	        into fields: inout [String: Any]
159	    ) throws {
160	        let (clips, scope) = onMain {
161	            (RecordingEnhance.voiceClips(of: result, in: document), document.scope)
162	        }
163	        let started = Date()
164	        var step = RecordingEnhance.Step.wait
165	        while step == .wait, stop?.isCancelled != true {
166	            step = onMain { () -> RecordingEnhance.Step in
167	                let present = RecordingEnhance.present(clips, in: document)
168	                return RecordingEnhance.decide(
169	                    clips: present, analysed: RecordingEnhance.isAnalysed(present, in: document),
170	                    busy: RecordingEnhance.isBusy(document, scope: scope),
171	                    elapsed: Date().timeIntervalSince(started))
172	            }
173	            if step == .wait { Thread.sleep(forTimeInterval: RecordingEnhance.checkInterval) }
174	        }
175	        switch step {
176	        case .enhance(let ids):
177	            do {
178	                let enhanced = try enhanceVoice(
179	                    document: document, clips: ids, targetLUFS: AudioNormalize.defaultTargetLUFS)
180	                fields["enhance"] = Self.resultObject(enhanced) ?? enhanced
181	            } catch let error as ToolError {
182	                fields["enhance_error"] = error.message
183	            }
184	        case .drop:
185	            fields["enhance_error"] = RecordingEnhance.noVoiceSentence
186	        case .giveUp:
187	            fields["enhance_error"] = RecordingEnhance.notReadyToolSentence
188	        case .wait:
189	            fields["enhance_error"] =
190	                "record_screen was stopped while the microphone's sound was being analysed, so "
191	                + "Enhance Voice did not run."
192	        }
193	    }
194	
195	    /// The object a `jsonResult` envelope's text holds, nil for anything else.
196	    static func resultObject(_ envelope: String) -> [String: Any]? {
197	        guard
198	            let call = (try? JSONSerialization.jsonObject(with: Data(envelope.utf8)))
199	                as? [String: Any],
200	            let content = call["content"] as? [[String: Any]],
201	            let text = content.first?["text"] as? String
202	        else { return nil }
203	        return (try? JSONSerialization.jsonObject(with: Data(text.utf8))) as? [String: Any]
204	    }
205	}
